:root {
  --ink: #100c08;
  --ink-2: #1a120b;
  --paper: #f4ead6;
  --dim: #a89c85;
  --rust: #ff5a1f;
  --rust-deep: #c9350d;
  --acid: #d5f25c;
  --cyan: #7fe7dc;
  --blood: #d51f2b;
  --line: rgba(244, 234, 214, .16);
  --panel: rgba(12, 9, 6, .72);
  --mono: 'Space Mono', ui-monospace, monospace;
  --display: 'Barlow Condensed', Impact, sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  background: var(--ink);
  color: var(--paper);
  font-family: var(--display);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--acid); outline-offset: 3px; }
canvas { display: block; }
.hidden { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  background: #2c1a10;
  outline: none;
  touch-action: none;
}

.screen-fx {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  overflow: hidden;
}
.grain {
  position: absolute;
  inset: -25%;
  opacity: .11;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.75'/%3E%3C/svg%3E");
  animation: grainShift .23s steps(2) infinite;
  mix-blend-mode: overlay;
}
@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1.5%, 0); }
  50% { transform: translate3d(1.5%, -1%, 0); }
  75% { transform: translate3d(-1%, -2%, 0); }
  100% { transform: translate3d(2%, 1%, 0); }
}
.scanlines {
  position: absolute;
  inset: 0;
  opacity: .12;
  background: repeating-linear-gradient(180deg, transparent 0, transparent 3px, rgba(7, 4, 2, .65) 4px);
}
.vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(8, 5, 3, .55) 100%);
}

/* ---------------- main menu ---------------- */
.menu {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  padding: clamp(18px, 3.2vw, 46px) clamp(20px, 4.5vw, 72px) clamp(16px, 2.2vw, 32px);
  transition: opacity .5s ease, visibility .5s;
}
.menu.out { opacity: 0; visibility: hidden; pointer-events: none; }
.menu-shade {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    linear-gradient(90deg, rgba(8, 5, 3, .91) 0%, rgba(8, 5, 3, .74) 35%, rgba(8, 5, 3, .28) 63%, rgba(8, 5, 3, .05) 100%),
    linear-gradient(0deg, rgba(8, 5, 3, .88) 0%, transparent 33%, transparent 72%, rgba(8, 5, 3, .62) 100%);
}
.topline {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
  flex: none;
}
.wordmark {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 800;
  font-size: 19px;
  letter-spacing: .18em;
}
.mark {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  background: var(--rust);
  color: var(--ink);
  clip-path: polygon(0 0, 100% 0, 100% 68%, 68% 100%, 0 100%);
  font-size: 18px;
  letter-spacing: -.05em;
  font-weight: 800;
}
.topline-meta {
  display: flex;
  align-items: center;
  gap: 17px;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .12em;
  color: var(--dim);
}
.live-dot {
  width: 6px;
  height: 6px;
  background: var(--acid);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--acid);
  animation: blink 2.2s infinite;
}
@keyframes blink { 0%, 85%, 100% { opacity: 1; } 90% { opacity: .25; } }
.build {
  padding: 6px 9px;
  border: 1px solid var(--line);
  color: var(--paper);
}

.menu-grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(440px, 1.22fr) minmax(300px, .58fr);
  align-items: center;
  gap: clamp(38px, 7vw, 120px);
  padding: clamp(16px, 3.5vh, 46px) 0;
}
.hero { max-width: 720px; position: relative; }
.eyebrow {
  display: flex;
  align-items: center;
  gap: 11px;
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 10px);
  letter-spacing: .18em;
  color: var(--acid);
  margin-bottom: 7px;
}
.eyebrow .line { width: 30px; height: 1px; background: var(--acid); }
.eyebrow .tag {
  margin-left: 7px;
  color: var(--ink);
  background: var(--acid);
  padding: 3px 6px 2px;
  letter-spacing: .08em;
}
h1 {
  font-size: clamp(84px, 13.4vw, 194px);
  line-height: .75;
  margin: 0 0 19px;
  letter-spacing: -.045em;
  font-weight: 800;
  text-shadow: 0 12px 50px rgba(0, 0, 0, .45);
  position: relative;
}
h1 span {
  color: transparent;
  -webkit-text-stroke: 2px var(--paper);
  text-stroke: 2px var(--paper);
  position: relative;
}
h1 span::after {
  content: '';
  position: absolute;
  left: .06em;
  right: -.02em;
  bottom: .02em;
  height: .08em;
  background: var(--rust);
  transform: skewX(-20deg);
  opacity: .9;
}
.lede {
  width: min(500px, 94%);
  margin: 0 0 clamp(15px, 2.1vh, 27px);
  font-family: var(--mono);
  font-size: clamp(9.5px, .85vw, 12px);
  line-height: 1.75;
  letter-spacing: .02em;
  color: #cfc2ac;
}
.mode-label {
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .23em;
  color: var(--dim);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
}
.mode-label::after { content: ''; height: 1px; flex: 1; background: var(--line); }
.modes { display: grid; gap: 7px; }
.mode-card {
  position: relative;
  display: grid;
  grid-template-columns: 79px 1fr 80px;
  align-items: center;
  gap: 14px;
  min-height: 73px;
  padding: 8px 15px 8px 9px;
  text-align: left;
  background: linear-gradient(90deg, rgba(242, 232, 212, .065), rgba(242, 232, 212, .025));
  border: 1px solid rgba(244, 234, 214, .15);
  border-left: 2px solid rgba(244, 234, 214, .18);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  transition: background .16s ease, border-color .16s ease, transform .16s ease;
}
.mode-card::after {
  content: '';
  position: absolute;
  right: 0;
  bottom: 0;
  border-style: solid;
  border-width: 0 0 13px 13px;
  border-color: transparent transparent rgba(244, 234, 214, .14) transparent;
}
.mode-card:hover { background: linear-gradient(90deg, rgba(244, 234, 214, .12), rgba(244, 234, 214, .03)); transform: translateX(2px); }
.mode-card.selected {
  border-color: var(--rust);
  border-left-color: var(--rust);
  background: linear-gradient(90deg, rgba(255, 90, 31, .18), rgba(255, 90, 31, .035) 72%);
}
.mode-card.selected::after { border-color: transparent transparent var(--rust) transparent; }
.mode-art {
  position: relative;
  width: 79px;
  height: 56px;
  overflow: hidden;
  background: linear-gradient(180deg, #4d2a1c, #1b110b 65%);
  border: 1px solid rgba(244, 234, 214, .13);
}
.mode-card.selected .mode-art { border-color: rgba(255, 90, 31, .45); }
.mode-art .sun {
  position: absolute;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #e8843a;
  top: 8px;
  right: 10px;
  box-shadow: 0 0 17px rgba(232, 132, 58, .7);
}
.art-zombie .skyline { position: absolute; left: 0; bottom: 12px; width: 100%; height: 10px; background: #2b1a12; clip-path: polygon(0 100%, 0 30%, 9% 30%, 9% 70%, 17% 70%, 17% 10%, 27% 10%, 27% 100%, 46% 100%, 46% 55%, 56% 55%, 56% 100%, 73% 100%, 73% 20%, 82% 20%, 82% 100%); }
.art-zombie .z-head { position: absolute; width: 12px; height: 12px; background: #9caa67; left: 35px; top: 17px; transform: rotate(-8deg); }
.art-zombie .z-head::after { content: ''; position: absolute; width: 3px; height: 3px; background: #ff5a1f; left: 3px; top: 4px; }
.art-zombie .z-body { position: absolute; width: 15px; height: 22px; background: #5f6545; left: 33px; top: 29px; transform: skewX(4deg); }
.art-zombie .z-arm { position: absolute; width: 5px; height: 21px; background: #8f9a5f; top: 29px; transform-origin: top; }
.art-zombie .z-arm.a { left: 30px; transform: rotate(32deg); }
.art-zombie .z-arm.b { left: 47px; transform: rotate(-23deg); }
.art-prop .barrel { position: absolute; width: 17px; height: 23px; background: linear-gradient(90deg, #7f3a1d, #c2622f 50%, #612714); left: 16px; bottom: 8px; }
.art-prop .barrel::before, .art-prop .barrel::after { content: ''; position: absolute; left: 1px; right: 1px; height: 2px; background: #35190e; }
.art-prop .barrel::before { top: 5px; } .art-prop .barrel::after { bottom: 5px; }
.art-prop .crate { position: absolute; width: 26px; height: 19px; background: #755534; left: 39px; bottom: 8px; border: 2px solid #3d2a18; }
.art-prop .crate::after { content: ''; position: absolute; inset: 3px; border: 1px solid #a57a4b; }
.art-prop .eye { position: absolute; width: 11px; height: 6px; border: 1px solid var(--acid); border-radius: 50%; left: 47px; bottom: 27px; box-shadow: 0 0 8px var(--acid); animation: propEye 4s infinite; }
.art-prop .eye::after { content: ''; position: absolute; width: 3px; height: 3px; border-radius: 50%; background: var(--acid); left: 4px; top: 1px; }
@keyframes propEye { 0%, 88%, 100% { opacity: 0; } 91%, 96% { opacity: 1; } }
.mode-copy { min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.mode-index { font-family: var(--mono); font-size: 7.5px; letter-spacing: .16em; color: var(--rust); }
.mode-copy strong { font-size: clamp(20px, 1.8vw, 27px); line-height: 1; font-weight: 700; letter-spacing: .02em; }
.mode-copy > span:last-child { font-family: var(--mono); font-size: 8px; color: var(--dim); letter-spacing: .01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mode-stat { font-family: var(--mono); font-size: 7px; letter-spacing: .12em; color: var(--dim); text-align: right; line-height: 1.5; }
.mode-stat b { display: block; font-family: var(--display); font-size: 24px; color: var(--paper); line-height: .9; }
.select-mark {
  position: absolute;
  right: 10px;
  top: 7px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .12em;
  color: var(--ink);
  background: var(--rust);
  padding: 2px 4px;
  opacity: 0;
}
.mode-card.selected .select-mark { opacity: 1; }
.mode-card.selected .mode-stat { color: var(--rust); }
.mode-card.selected .mode-stat b { color: var(--paper); }

.launch-row {
  display: flex;
  align-items: center;
  gap: clamp(13px, 2vw, 25px);
  margin-top: clamp(14px, 2.1vh, 25px);
}
.play-btn {
  position: relative;
  width: clamp(200px, 21vw, 280px);
  min-height: 60px;
  padding: 11px 45px 11px 22px;
  text-align: left;
  background: var(--rust);
  color: #160c06;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 17px), calc(100% - 17px) 100%, 0 100%);
  transition: filter .15s, transform .15s;
}
.play-btn::before {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(18, 10, 5, .32);
  clip-path: inherit;
  pointer-events: none;
}
.play-btn:hover { filter: brightness(1.12); transform: translateY(-1px); }
.play-btn:active { transform: translateY(1px); }
.play-label { display: block; font-size: 28px; line-height: .92; font-weight: 800; letter-spacing: .045em; }
.play-sub { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: .16em; margin-top: 4px; opacity: .72; }
.play-arrow { position: absolute; right: 17px; top: 17px; font-family: var(--mono); font-size: 23px; }
.launch-note { font-family: var(--mono); font-size: 7.5px; letter-spacing: .1em; color: var(--dim); line-height: 1.8; }
.launch-note span { display: block; color: var(--paper); }
.launch-note small { display: block; margin-top: 3px; opacity: .67; font-size: 6.8px; }

.intel {
  width: min(100%, 344px);
  justify-self: end;
  align-self: center;
  border: 1px solid var(--line);
  background: linear-gradient(155deg, rgba(17, 12, 8, .82), rgba(10, 7, 4, .55));
  backdrop-filter: blur(9px);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 0 100%);
  position: relative;
}
.intel::before { content: ''; position: absolute; top: 0; right: 0; width: 31px; height: 31px; border-left: 1px solid var(--line); transform: rotate(-45deg) translate(-4px, -17px); opacity: .8; }
.intel-head { display: flex; justify-content: space-between; padding: 12px 16px 10px; border-bottom: 1px solid var(--line); font-family: var(--mono); font-size: 8px; letter-spacing: .18em; color: var(--rust); }
.intel-code { color: var(--dim); }
.intel-body { padding: 17px 19px 15px; position: relative; overflow: hidden; }
.brief-no { position: absolute; right: 12px; top: 2px; font-size: 60px; font-weight: 800; color: rgba(244, 234, 214, .055); line-height: 1; }
.intel-body h2 { font-size: 29px; line-height: .9; margin: 0 0 10px; letter-spacing: .015em; font-weight: 700; }
.intel-body p { font-family: var(--mono); font-size: 8px; line-height: 1.8; color: var(--dim); margin: 0; max-width: 280px; }
.intel-tags { display: flex; gap: 5px; margin-top: 12px; }
.intel-tags span { font-family: var(--mono); font-size: 6px; letter-spacing: .11em; border: 1px solid rgba(244, 234, 214, .2); padding: 3px 5px; color: #cbbfa9; }
.controls { border-top: 1px solid var(--line); padding: 12px 16px 10px; }
.controls-head { font-family: var(--mono); font-size: 7px; letter-spacing: .2em; color: var(--dim); margin-bottom: 7px; }
.control-row { display: flex; align-items: center; justify-content: space-between; min-height: 23px; padding: 2px 0; border-top: 1px solid rgba(244, 234, 214, .06); font-family: var(--mono); font-size: 7px; letter-spacing: .06em; color: var(--dim); }
.control-row:first-of-type { border-top: 0; }
.control-row em { font-style: normal; color: var(--acid); font-size: 5.8px; margin-left: 4px; }
.keys { display: flex; gap: 3px; align-items: center; }
kbd { font-family: var(--mono); font-size: 6.5px; color: var(--paper); border: 1px solid rgba(244, 234, 214, .23); background: rgba(244, 234, 214, .06); min-width: 20px; padding: 2px 4px; text-align: center; border-bottom-color: rgba(244, 234, 214, .35); }
.intel-foot { display: flex; justify-content: space-between; align-items: center; padding: 9px 16px; border-top: 1px solid var(--line); font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--dim); }
.stamp { color: var(--ink); background: var(--acid); padding: 3px 5px; letter-spacing: .16em; }
.menu-foot { display: flex; justify-content: space-between; align-items: center; font-family: var(--mono); font-size: 6.5px; letter-spacing: .12em; color: rgba(203, 191, 169, .5); border-top: 1px solid rgba(244, 234, 214, .09); padding-top: 11px; flex: none; }

/* ---------------- HUD ---------------- */
.hud { position: fixed; inset: 0; z-index: 6; pointer-events: none; transition: opacity .25s; }
.hud-top { position: absolute; top: max(18px, env(safe-area-inset-top)); left: 22px; right: 22px; display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; }
.player-panel {
  width: 235px;
  padding: 11px 13px 9px;
  background: linear-gradient(100deg, rgba(9, 6, 4, .82), rgba(9, 6, 4, .4));
  border-left: 2px solid var(--acid);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
}
.operator-row { display: flex; gap: 10px; align-items: center; margin-bottom: 8px; }
.operator-icon { width: 24px; height: 24px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--acid); font-size: 13px; }
.hud-kicker { font-family: var(--mono); font-size: 6.5px; letter-spacing: .2em; color: var(--dim); }
.operator-name { font-size: 17px; line-height: 1.05; letter-spacing: .07em; font-weight: 700; }
.operator-name span { font-family: var(--mono); font-size: 6px; color: var(--dim); letter-spacing: .08em; }
.health-row { display: flex; align-items: center; gap: 9px; }
.health-bar { height: 11px; flex: 1; background: rgba(244, 234, 214, .12); position: relative; overflow: hidden; }
.health-bar > i { position: absolute; inset: 0; width: 100%; background: linear-gradient(90deg, var(--rust-deep), var(--rust) 68%, #ff9d45); transform-origin: left; transition: transform .22s; }
.health-ticks { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(10, 6, 4, .5) calc(10% - 1px), rgba(10, 6, 4, .5) 10%); }
.health-row b { font-family: var(--mono); font-size: 17px; font-weight: 400; min-width: 29px; text-align: right; }
.health-label { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 5.5px; letter-spacing: .14em; margin-top: 3px; color: var(--dim); }
#healthState { color: var(--acid); }

.objective-panel { width: 265px; margin-top: 2px; text-align: center; position: relative; }
.objective-top { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 6.5px; letter-spacing: .16em; color: var(--dim); }
#objectiveKicker { color: var(--rust); }
.objective-main { font-size: 34px; font-weight: 800; line-height: 1; letter-spacing: .05em; text-shadow: 0 2px 15px rgba(0, 0, 0, .6); }
.objective-sub { font-family: var(--mono); font-size: 6.5px; letter-spacing: .16em; color: var(--dim); margin-top: 2px; }
.objective-track { height: 2px; background: rgba(244, 234, 214, .2); margin-top: 8px; overflow: hidden; }
.objective-track i { display: block; height: 100%; width: 0%; background: var(--rust); transition: width .25s; }
.score-panel { width: 170px; text-align: right; padding-top: 3px; }
.score-num { font-family: var(--mono); font-size: 26px; letter-spacing: .03em; line-height: 1.1; text-shadow: 0 2px 10px rgba(0, 0, 0, .5); }
.score-meta { display: flex; justify-content: flex-end; gap: 14px; font-family: var(--mono); font-size: 6px; letter-spacing: .1em; color: var(--dim); }
.score-meta b { color: var(--paper); font-weight: 400; }

.killfeed { position: absolute; right: 23px; top: 100px; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.kill-item { font-family: var(--mono); font-size: 7px; letter-spacing: .08em; padding: 5px 8px; background: rgba(9, 6, 4, .72); border-right: 2px solid var(--rust); color: #d8cdb8; animation: killIn .22s ease-out; }
.kill-item b { color: var(--acid); font-weight: 400; }
.kill-item.head b { color: var(--rust); }
.kill-item.out { opacity: 0; transition: opacity .35s; }
@keyframes killIn { from { transform: translateX(15px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }

.hud-bottom { position: absolute; left: 22px; right: 22px; bottom: max(18px, env(safe-area-inset-bottom)); display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; }
.radar-wrap { width: 155px; height: 155px; position: relative; flex: none; border-radius: 50%; background: rgba(8, 5, 3, .5); border: 1px solid rgba(244, 234, 214, .18); }
#radar { width: 100%; height: 100%; border-radius: 50%; opacity: .94; }
.radar-ring { position: absolute; inset: 13px; border: 1px solid rgba(244, 234, 214, .09); border-radius: 50%; }
.radar-ring::after { content: ''; position: absolute; left: 50%; top: 0; bottom: 0; width: 1px; background: rgba(244, 234, 214, .09); }
.radar-label { position: absolute; left: 50%; bottom: -6px; transform: translateX(-50%); display: flex; gap: 5px; white-space: nowrap; font-family: var(--mono); font-size: 5.5px; letter-spacing: .11em; color: var(--dim); background: rgba(8, 5, 3, .7); padding: 2px 5px; }
.radar-label b { color: var(--acid); font-weight: 400; }
.hint-bar { font-family: var(--mono); font-size: 6.5px; letter-spacing: .11em; color: rgba(203, 191, 169, .62); padding-bottom: 3px; opacity: 0; animation: hintIn .3s 1.5s forwards; }
@keyframes hintIn { to { opacity: 1; } }
.hint-bar span { margin: 0 7px; opacity: .5; }
.weapon-panel { width: 265px; text-align: right; }
.reload-bar { height: 13px; margin-bottom: 5px; background: rgba(9, 6, 4, .6); border: 1px solid rgba(244, 234, 214, .15); position: relative; display: none; }
.reload-bar.on { display: block; }
.reload-bar i { display: block; height: 100%; width: 0%; background: var(--rust); transition: width .1s linear; }
.reload-bar span { position: absolute; inset: 0; text-align: center; font-family: var(--mono); font-size: 5.5px; line-height: 11px; letter-spacing: .2em; color: var(--paper); }
.ammo-line { display: flex; justify-content: flex-end; align-items: flex-end; gap: 12px; }
.weapon-name { text-align: right; font-size: 16px; line-height: 1; letter-spacing: .05em; font-weight: 700; }
.weapon-name > span { font-family: var(--mono); font-size: 6px; color: var(--rust); vertical-align: middle; margin-right: 3px; }
.weapon-name small { display: block; font-family: var(--mono); font-size: 5.5px; font-weight: 400; letter-spacing: .14em; color: var(--dim); margin-top: 3px; }
.ammo { line-height: .8; }
.ammo b { font-family: var(--display); font-size: 45px; font-weight: 700; letter-spacing: -.03em; }
.ammo span { font-family: var(--mono); font-size: 9px; color: var(--dim); margin-left: 2px; }
.weapon-pips { display: flex; gap: 4px; margin-top: 7px; pointer-events: auto; }
.weapon-pips button { flex: 1; position: relative; display: flex; align-items: center; gap: 5px; padding: 5px 7px; border: 1px solid rgba(244, 234, 214, .13); background: rgba(9, 6, 4, .55); font-family: var(--mono); font-size: 6px; letter-spacing: .09em; color: var(--dim); text-align: left; }
.weapon-pips button span { color: var(--paper); border: 1px solid rgba(244, 234, 214, .18); padding: 1px 3px; font-size: 5px; }
.weapon-pips button.active { border-color: var(--rust); color: var(--paper); background: rgba(255, 90, 31, .14); }
.weapon-pips button i { position: absolute; left: 7px; right: 7px; bottom: 3px; height: 1px; background: var(--rust); transform: scaleX(0); transform-origin: left; transition: transform .1s; }
.weapon-pips button.active i { transform: scaleX(1); }
.charge-row { display: flex; align-items: center; justify-content: flex-end; gap: 7px; margin-top: 7px; font-family: var(--mono); font-size: 5.5px; letter-spacing: .12em; color: var(--dim); }
.charge-row b { color: var(--paper); border: 1px solid var(--line); padding: 1px 4px; font-weight: 400; }
.charge-meter { width: 58px; height: 3px; background: rgba(244, 234, 214, .15); }
.charge-meter i { display: block; height: 100%; width: 100%; background: var(--cyan); transform-origin: left; }
.charge-row.ready #chargeLabel { color: var(--cyan); }

.crosshair { position: absolute; left: 50%; top: 50%; width: 0; height: 0; --gap: 8px; --len: 8px; transition: opacity .15s; }
.crosshair .ch { position: absolute; background: rgba(244, 234, 214, .95); box-shadow: 0 0 2px rgba(0, 0, 0, .95); }
.crosshair .top { width: 1.5px; height: var(--len); left: -.75px; top: calc(-1 * var(--gap) - var(--len)); }
.crosshair .bottom { width: 1.5px; height: var(--len); left: -.75px; top: var(--gap); }
.crosshair .left { width: var(--len); height: 1.5px; top: -.75px; left: calc(-1 * var(--gap) - var(--len)); }
.crosshair .right { width: var(--len); height: 1.5px; top: -.75px; left: var(--gap); }
.crosshair .dot { position: absolute; width: 2px; height: 2px; background: var(--rust); left: -1px; top: -1px; border-radius: 50%; }
.crosshair.enemy .ch { background: var(--rust); }
.crosshair.ads { opacity: .5; }
.hitmarker { position: absolute; left: 50%; top: 50%; width: 34px; height: 34px; transform: translate(-50%, -50%) scale(.5); opacity: 0; }
.hitmarker i { position: absolute; width: 9px; height: 2px; background: var(--paper); left: 50%; top: 50%; box-shadow: 0 0 3px rgba(0, 0, 0, .9); }
.hitmarker i:nth-child(1) { transform: translate(-14px, -9px) rotate(45deg); }
.hitmarker i:nth-child(2) { transform: translate(5px, -9px) rotate(-45deg); }
.hitmarker i:nth-child(3) { transform: translate(-14px, 7px) rotate(-45deg); }
.hitmarker i:nth-child(4) { transform: translate(5px, 7px) rotate(45deg); }
.hitmarker.show { animation: hitPop .25s ease-out; }
.hitmarker.kill i { background: var(--rust); height: 3px; }
@keyframes hitPop { 0% { opacity: 1; transform: translate(-50%, -50%) scale(.55); } 45% { opacity: 1; transform: translate(-50%, -50%) scale(1); } 100% { opacity: 0; transform: translate(-50%, -50%) scale(1.15); } }

.damage-flash { position: absolute; inset: 0; opacity: 0; background: radial-gradient(ellipse at center, transparent 42%, rgba(150, 7, 7, .72) 100%); transition: opacity .35s; }
.damage-flash.on { opacity: 1; transition: opacity .04s; }
.low-health { position: absolute; inset: 0; opacity: 0; background: radial-gradient(ellipse at center, transparent 42%, rgba(115, 4, 5, .55) 100%); }
.low-health.on { animation: heartPulse 1.4s infinite; }
@keyframes heartPulse { 0%, 100% { opacity: .25; } 12% { opacity: .75; } 25% { opacity: .3; } 40% { opacity: .55; } }
.banner { position: absolute; left: 50%; top: 31%; transform: translate(-50%, -50%) scale(.9); text-align: center; opacity: 0; transition: opacity .25s, transform .35s; text-shadow: 0 3px 20px rgba(0, 0, 0, .7); }
.banner.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.banner-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: .38em; color: var(--rust); }
.banner-main { font-size: clamp(48px, 6vw, 78px); font-weight: 800; line-height: .9; letter-spacing: .04em; }
.banner-sub { font-family: var(--mono); font-size: 7px; letter-spacing: .3em; color: var(--dim); margin-top: 5px; }
.pickup-toast { position: absolute; left: 50%; bottom: 23%; transform: translateX(-50%); font-family: var(--mono); font-size: 8px; letter-spacing: .15em; color: var(--acid); opacity: 0; transition: opacity .3s; text-shadow: 0 1px 4px #000; }
.pickup-toast.on { opacity: 1; }
.mouse-hint { position: absolute; left: 50%; top: 57%; transform: translateX(-50%); font-family: var(--mono); font-size: 7px; letter-spacing: .18em; color: rgba(244, 234, 214, .72); background: rgba(7, 4, 3, .6); padding: 7px 11px; border: 1px solid var(--line); opacity: 0; transition: opacity .3s; }
.mouse-hint.on { opacity: 1; }

.world-layer { position: absolute; inset: 0; overflow: hidden; }
.dmg-num { position: absolute; font-family: var(--mono); font-size: 10px; color: var(--paper); text-shadow: 0 1px 3px #000; transform: translate(-50%, -50%); animation: dmgFloat .55s ease-out forwards; white-space: nowrap; }
.dmg-num.head { color: var(--rust); font-size: 13px; }
@keyframes dmgFloat { 0% { opacity: 0; margin-top: 6px; } 15% { opacity: 1; } 100% { opacity: 0; margin-top: -24px; } }

/* ---------------- modal ---------------- */
.modal-screen { position: fixed; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center; background: rgba(7, 4, 3, .68); backdrop-filter: blur(8px); padding: 20px; transition: opacity .25s; }
.modal-card { width: min(420px, 100%); padding: 27px 28px 24px; background: linear-gradient(150deg, rgba(28, 20, 13, .97), rgba(12, 8, 5, .98)); border: 1px solid rgba(244, 234, 214, .19); position: relative; clip-path: polygon(0 0, calc(100% - 25px) 0, 100% 25px, 100% 100%, 0 100%); }
.modal-card::after { content: ''; position: absolute; left: 0; top: 0; width: 4px; height: 70px; background: var(--rust); }
.modal-kicker { font-family: var(--mono); font-size: 7px; letter-spacing: .24em; color: var(--rust); margin-bottom: 5px; }
.modal-card h2 { font-size: 68px; line-height: .82; margin: 0 0 8px; letter-spacing: .015em; font-weight: 800; }
.modal-card > p { font-family: var(--mono); font-size: 8px; line-height: 1.6; color: var(--dim); margin: 0 0 18px; }
.pause-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); margin-bottom: 20px; }
.pause-stats div { background: #17100a; padding: 9px 10px; }
.pause-stats span { display: block; font-family: var(--mono); font-size: 5.5px; letter-spacing: .14em; color: var(--dim); }
.pause-stats b { font-family: var(--mono); font-size: 16px; font-weight: 400; }
.primary-btn { display: flex; justify-content: space-between; align-items: center; width: 100%; padding: 13px 16px; background: var(--rust); color: #190d06; font-size: 21px; font-weight: 700; letter-spacing: .06em; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%); }
.primary-btn:hover { filter: brightness(1.12); }
.primary-btn span { font-family: var(--mono); font-size: 18px; }
.ghost-btn { display: block; width: 100%; padding: 10px; margin-top: 5px; font-family: var(--mono); font-size: 7px; letter-spacing: .16em; color: var(--dim); border: 1px solid rgba(244, 234, 214, .1); }
.ghost-btn:hover { color: var(--paper); border-color: rgba(244, 234, 214, .28); }
.end-card { width: min(470px, 100%); }
.end-card h2 { font-size: 78px; }
.end-grade { position: absolute; right: 23px; top: 65px; text-align: center; }
.end-grade span { display: block; font-family: var(--mono); font-size: 5.5px; letter-spacing: .12em; color: var(--dim); }
.end-grade b { display: block; font-size: 50px; line-height: .9; color: var(--acid); font-weight: 800; }
.end-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line); margin-bottom: 18px; }
.end-stats div { background: #17100a; padding: 7px 10px; display: flex; justify-content: space-between; align-items: baseline; }
.end-stats span { font-family: var(--mono); font-size: 5.5px; letter-spacing: .1em; color: var(--dim); }
.end-stats b { font-family: var(--mono); font-size: 11px; font-weight: 400; }

/* ---------------- touch ---------------- */
.touch { position: fixed; inset: 0; z-index: 8; pointer-events: none; }
.touch button { pointer-events: auto; touch-action: none; }
.stick { position: absolute; width: 118px; height: 118px; left: max(20px, env(safe-area-inset-left)); bottom: max(22px, env(safe-area-inset-bottom)); border: 1px solid rgba(244, 234, 214, .3); border-radius: 50%; background: rgba(8, 5, 3, .3); pointer-events: auto; }
.stick::before { content: ''; position: absolute; inset: 17px; border: 1px dashed rgba(244, 234, 214, .17); border-radius: 50%; }
.stick i { position: absolute; width: 44px; height: 44px; left: 37px; top: 37px; background: rgba(244, 234, 214, .2); border: 1px solid rgba(244, 234, 214, .55); border-radius: 50%; }
.stick span { position: absolute; left: 50%; bottom: 5px; transform: translateX(-50%); font-family: var(--mono); font-size: 5px; letter-spacing: .18em; color: rgba(244, 234, 214, .5); }
.touch-right { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(22px, env(safe-area-inset-bottom)); width: 150px; height: 210px; }
