+    vel.addScaledVector(side, rand(-1.5, 1.5) * force);
+    vel.y = rand(1.4, 3.8) * force * (isHead ? 1.3 : 1);
+    const pivotToBase = Math.max(.06, clone.position.y - box.min.y);
+    corpses.push({
+      obj: clone,
