+  }
+  // faint mimic eyes (only visible on scan)
+  for (const sx of [-.1, .1]) {
+    const eye = new THREE.Mesh(new THREE.BoxGeometry(.07, .035, .02), new THREE.MeshBasicMaterial({ color: 0x8ffff0 }));
