+  glow.position.z = .35;
+  group.add(glow);
+  group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, -1), dir);
+  scene.add(group);
+  state.projectiles.push({
+    mesh: group,
+    vel: dir.clone().multiplyScalar(36),
