+  // ring
+  const ringMat = new THREE.MeshBasicMaterial({ color: 0xffb86c, transparent: true, opacity: .85, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
+  const ring = new THREE.Mesh(GEO.ring, ringMat);
