+  activeGroup.rotation.y = damp(activeGroup.rotation.y, ads ? 0 : .025 + bobX * .2, 12, dt);
+  activeGroup.rotation.z = damp(activeGroup.rotation.z, ads ? 0 : -.015 + Math.sin(player.bobTime * bobSpeed * .5) * .008 * player.moveAmount, 12, dt);
+  w.kick = damp(w.kick, 0, isAK ? 17 : 10, dt);
+  if (weaponSwitchTimer > 0) {
+    activeGroup.position.y -= .2 * (weaponSwitchTimer / .28);
+  }
+  // camera fov
+  const targetFov = ads ? (isAK ? 57 : 53) : 71;
+  camera.fov = damp(camera.fov, targetFov, 15, dt);
+  camera.updateProjectionMatrix();
+}
+
+function switchWeapon(key) {
