import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
page.on('console', m => console.log('[console]', m.text()))
const t0 = Date.now()
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 45000 })
console.log('load', Date.now() - t0, 'ms')
await page.waitForFunction(() => document.fonts.status === 'loaded')
console.log('fonts', Date.now() - t0, 'ms')
for (let i = 0; i < 6; i++) {
  const info = await page.evaluate(() => new Promise(res => {
    const t = performance.now()
    let n = 0
    const tick = () => { n++; if (performance.now() - t < 1000) requestAnimationFrame(tick); else res({ fps: n, menuIdle: window.DEAD_DROP?.menuIdle, frames: window.DEAD_DROP?.renderer?.info?.render?.frame }) }
    requestAnimationFrame(tick)
  }))
  console.log(i, info, 'at', Date.now() - t0)
  // bbox samples
  const boxes = await page.evaluate(async () => {
    const el = document.querySelector('#playBtn')
    const out = []
    for (let i = 0; i < 4; i++) {
      const r = el.getBoundingClientRect()
      out.push([r.x, r.y, r.width, r.height, getComputedStyle(el).transform])
      await new Promise(r => requestAnimationFrame(r))
    }
    return out
  })
  console.log('  boxes', JSON.stringify(boxes))
}
const start = Date.now()
try {
  await page.locator('#playBtn').click({ trial: true, timeout: 8000 })
  console.log('trial ok after', Date.now() - start, 'ms')
} catch (e) {
  console.log('trial fail after', Date.now() - start, 'ms:', e.message.split('\n')[0])
}
await browser.close()

