import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const variant = process.argv[2]
const css = variant === 'none' ? '' : variant === 'nodisplay' ? '.grain{display:none!important}' : variant === 'noanim' ? '.grain{animation:none!important}' : variant === 'noblend' ? '.grain{mix-blend-mode:normal!important}' : variant === 'small' ? '.grain{inset:0!important;animation:none!important}' : variant === 'allanim' ? '*{animation:none!important}' : ''
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.setDefaultTimeout(30000)
if (css) await page.addInitScript((css) => { addEventListener('DOMContentLoaded', () => { const s = document.createElement('style'); s.textContent = css; document.head.appendChild(s) }) }, css)
const t0 = Date.now()
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 45000 })
const tload = Date.now() - t0
await page.waitForFunction(() => document.fonts.status === 'loaded')
const tfonts = Date.now() - t0
let firstFps = null, firstAt = null
for (let i = 0; i < 8; i++) {
  const info = await page.evaluate(() => new Promise(res => {
    const t = performance.now(); let n = 0
    const tick = () => { n++; if (performance.now() - t < 500) res(Math.round(n / ((performance.now() - t) / 1000))); else requestAnimationFrame(tick) }
    requestAnimationFrame(tick)
  }))
  if (info >= 30 && firstFps === null) { firstFps = info; firstAt = Date.now() - t0; break }
}
const start = Date.now()
let trial = 'ok'
try { await page.locator('#playBtn').click({ trial: true, timeout: 2000 }) } catch (e) { trial = 'FAIL ' + e.message.split('\n')[0] }
console.log(JSON.stringify({ variant, tload, tfonts, firstFps, firstAt, trialMs: Date.now() - start, trial }))
await browser.close()
